199	        fun postProxyNotification(context: Context, item: NotificationItem, silent: Boolean, useSourceIcon: Boolean = false): PostResult = NotificationDiagnostics.trace("farhan.delivery.post") {
200	            val capabilities = actionStore.get(item.id)
201	            val builder = NotificationCompat.Builder(context, PROXY_CHANNEL_ID)
202	                .setContentTitle("Farhan · " + (item.title?.takeIf { it.isNotBlank() } ?: item.appName ?: "Notification"))
203	                .setContentText(item.text).setSubText(item.appName).setAutoCancel(true)
204	                .setPriority(NotificationCompat.PRIORITY_HIGH).setOnlyAlertOnce(true).setSilent(silent)
205	                .setCategory(NotificationCompat.CATEGORY_MESSAGE).setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
206	            // The source icon is an opt-in experiment; Farhan's icon is the fallback. Identity and channel stay Farhan's.
207	            val sourceIcon = if (useSourceIcon) usableSourceIcon(context, capabilities?.smallIcon) else null
208	            if (sourceIcon != null) builder.setSmallIcon(sourceIcon) else builder.setSmallIcon(R.drawable.ic_farhan_transparent)
209	            if (!silent) builder.setDefaults(NotificationCompat.DEFAULT_ALL)
210	            val tap = capabilities?.tap ?: context.packageManager.getLaunchIntentForPackage(item.packageName)?.let {
211	                PendingIntent.getActivity(context, item.id.hashCode(), it, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)
212	            }
213	            tap?.let { builder.setContentIntent(it) }
214	            capabilities?.replies?.forEach { captured ->
215	                val action = NotificationCompat.Action.Builder(0, captured.title, captured.actionIntent)
216	                captured.remoteInputs?.forEach { input -> action.addRemoteInput(AndroidXRemoteInput.Builder(input.resultKey)
217	                    .setLabel(input.label).setAllowFreeFormInput(input.allowFreeFormInput).build()) }
218	                builder.addAction(action.build())
219	            }
220	            if (Build.VERSION.SDK_INT >= 33 && androidx.core.content.ContextCompat.checkSelfPermission(context,
221	                    android.Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) {
222	                PostResult.Failed("notification_permission_denied")
223	            } else {
224	                val manager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
225	                if (Build.VERSION.SDK_INT >= 24 && !manager.areNotificationsEnabled()) PostResult.Failed("notifications_disabled")
226	                else if (Build.VERSION.SDK_INT >= 26 && manager.getNotificationChannel(PROXY_CHANNEL_ID)?.importance == NotificationManager.IMPORTANCE_NONE)
227	                    PostResult.Failed("notification_channel_disabled")
228	                else {
229	                    val proxies = manager.activeNotifications.filter { it.tag?.startsWith(PROXY_TAG) == true }
230	                    if (proxies.size >= MAX_LIVE_PROXIES && proxies.none { it.tag == PROXY_TAG + item.id }) PostResult.Failed("proxy_capacity_reached")
231	                    else { manager.notify(PROXY_TAG + item.id, 1, builder.build()); PostResult.Posted }
232	                }
233	            }
234	        }
