314	    override fun onNotificationPosted(sbn: StatusBarNotification?) {
315	        if (sbn == null || sbn.packageName == packageName) return
316	        snoozeIntake.routePosted(sbn.key, sbn.postTime, offer = { intake.offer(Work.Return) }) {
317	            if (preferences.isNotificationServiceStatsEnabled()) offerFreshPost(sbn)
318	            else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
319	                intake.offer(Work.CustodyCheck(sbn.key, sbn.postTime))
320	            }
321	        }
322	    }
