324	    private fun offerFreshPost(sbn: StatusBarNotification) {
325	        val notification = sbn.notification ?: return
326	        val groupKey = notification.group
327	        val flags = SnoozeExclusionFlags.fromNotification(notification.flags, notification.category, groupKey)
328	        val order = coordinator.captureEvent(sbn.key)
329	        // Copy only relevant fields. The bounded mailbox never retains StatusBarNotification/Notification.
330	        val item = NotificationItem(sbn.key, null,
331	            notification.extras?.getCharSequence(Notification.EXTRA_TITLE)?.toString()?.take(1024),
332	            notification.extras?.getCharSequence(Notification.EXTRA_TEXT)?.toString()?.take(16384),
333	            java.text.SimpleDateFormat("HH:mm", java.util.Locale.getDefault()).format(java.util.Date(sbn.postTime)),
334	            sbn.packageName, timestamp = sbn.postTime, channelId = notification.channelId)
335	        val actions = notification.actions.orEmpty().take(8).mapNotNull { action ->
336	            val intent = action.actionIntent ?: return@mapNotNull null
337	            CapturedAction(action.title?.toString()?.take(128).orEmpty(), intent, action.remoteInputs?.take(8)?.toTypedArray())
338	        }
339	        val smallIcon = if (preferences.isExperimentEnabled(Experiments.SOURCE_ICON)) notification.smallIcon else null
340	        val fields = PostedFields(item, notification.category, flags, groupKey, sbn.groupKey,
341	            notification.contentIntent, actions, order, smallIcon)
342	        if (!intake.offer(Work.Posted(fields))) {
343	            // Invalidate older queued updates to this key; this new notification remains in the source tray.
344	            coordinator.captureEvent(item.id, bypassed = true)
345	            actionStore.remove(item.id)
346	            NotificationDiagnostics.increment("farhan.intake.overflow")
347	        }
348	    }
