369	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
370	        snoozeWork.withLock {
371	            val now = Instant.now()
372	            val input = returnInput(now)
373	            val previous = previousSnoozeTick(now, input.zone, input.testingMode)
374	            drainSnoozeReturns()
375	            snoozeHandler.onBatchTick(now, previous)
376	        }
377	    }
