379	    private suspend fun processNotificationPosted(fields: PostedFields) {
380	        // A callback can arrive before the scan restores the binder-side cache.
381	        if (snoozeRouting.handleStoredPost(fields.item, fields.order, Instant.now())) return
382	        if (!notificationFilterUseCases.checkIfNotificationServiceIsEnabled()) return
383	        val pkg = fields.item.packageName
384	        val name = knownPackageSourceRegistry.get(pkg)?.appName ?: resolveApplicationName(pkg)
385	        notificationFilterUseCases.registerKnownNotificationSources(listOf(VisibleNotificationSource(pkg, name, fields.item.channelId, fields.androidCategory)))
386	        val source = knownPackageSourceRegistry.get(pkg)
387	        val (base, category) = NotificationDiagnostics.trace("farhan.classification") {
388	            notificationFilterUseCases.classifyNotification(fields.androidCategory, pkg, fields.item.channelId,
389	                source?.appCategoryCode, source?.androidCategories.orEmpty())
390	        }
391	        val channelOverride = fields.item.channelId?.let { preferences.getChannelPriorityOffset(pkg, it) != 0 } == true
392	        val locked = preferences.isAppPriorityLocked(pkg)
393	        val overridden = preferences.getAppPriorityOverride(pkg) != null
394	        val (priority, reason) = when {
395	            channelOverride || overridden -> base to "Set by user"
396	            locked -> base to "Locked by user"
397	            else -> applyDynamicAdjustments(base, pkg)
398	        }
399	        val excepted = preferences.isPackageInNotificationExceptions(pkg)
400	        val passThrough = fields.exclusionFlags.isSystemExemptCategory || excepted || priority == NotificationPriority.CRITICAL
401	        val item = fields.item.copy(appName = name, priority = priority, category = category, priorityReason = reason)
402	        val captureActions = {
403	            actionStore.put(item.id, Actions(fields.contentIntent, fields.actions, fields.smallIcon))
404	            NotificationDiagnostics.counter("farhan.actions.retained", actionStore.size())
405	        }
406	        val snoozeEnabled = preferences.isExperimentEnabled(Experiments.SNOOZE)
407	        val handled = routeSnoozeAdmission(snoozeEnabled, fields.exclusionFlags, admit = {
408	            if (activeSourcePostTimes()[item.id] != item.timestamp) return@routeSnoozeAdmission false
409	            val setting = preferences.getPriorityDeliverySettings()[priority] ?: PriorityDeliverySetting.defaultFor(priority)
410	            val filterEnabled = snoozeReturnFilterEnabled(preferences)
411	            val testingMode = preferences.isDeliveryTestingMode()
412	            coordinator.withSnoozeAdmission(item.id, fields.order) { liveRows, budget ->
413	                if (activeSourcePostTimes()[item.id] != item.timestamp) return@withSnoozeAdmission false
414	                val previous = notificationDao.find(item.id)
415	                val context = SnoozeInput(
416	                    packageName = pkg, ownPackageName = packageName, snoozeEnabled = snoozeEnabled,
417	                    filterEnabled = filterEnabled, platformSupportsSnooze = Build.VERSION.SDK_INT >= Build.VERSION_CODES.O,
418	                    setting = setting, now = Instant.now(), zone = DeliveryClock.systemClock.zone, testingMode = testingMode,
419	                    priority = priority, exclusionFlags = fields.exclusionFlags, isPassthrough = passThrough,
420	                    isExceptedPackage = excepted, alreadyDelivered = previous?.isDelivered == true && !previous.isCleared,
421	                    scheduleAt = { at, zone -> preferences.getScheduleSnapshot().book.scheduleAt(at, zone) },
422	                    liveSnoozes = liveRows.size, budget = budget, ownedRows = liveRows,
423	                    // CLAIM(snooze-group-device): grouped children return with their summary [F1-F3, F5 hidden-child].
424	                    groupSnoozeVerified = true,
425	                )
426	                snoozeHandler.onPosted(item.copy(snoozeGroupKey = fields.groupKey), context)
427	            }
428	        }, onAdmitted = captureActions)
429	        if (handled) return
430	        val outcome = coordinator.onArrival(item, priority, fields.order, passThrough, captureActions,
431	            sourceStillCurrent = { activeSourcePostTimes()[item.id] == item.timestamp })
432	        if (!passThrough && outcome !is DeliveryOutcome.Cleared && activeSourcePostTimes()[item.id] == item.timestamp) {
433	            if (fields.exclusionFlags.isGroupSummary) {
434	                summaryCancellations.requested(fields.androidGroupKey, item.id, item.timestamp)
435	            }
436	            cancelNotification(item.id)
437	        }
438	        if (outcome is DeliveryOutcome.Cleared) actionStore.remove(item.id)
439	        if (!passThrough && notificationFilterUseCases.getNotifyMeHour() != -1) {
440	            notificationFilterUseCases.createNotifyMeNotificationChannel()
441	            notificationFilterUseCases.scheduleNotifyMeNotification(notificationFilterUseCases.getNotifyMeHour(), notificationFilterUseCases.getNotifyMeMinute())
442	        }
443	    }
