460	    override fun onNotificationRemoved(sbn: StatusBarNotification?, rankingMap: RankingMap?, reason: Int) {
461	        if (sbn != null && sbn.packageName != packageName) {
462	            if (sbn.notification.flags and Notification.FLAG_GROUP_SUMMARY != 0) {
463	                summaryCancellations.summaryRemoved(sbn.groupKey, sbn.key, sbn.postTime, reason == REASON_LISTENER_CANCEL)
464	            }
465	            if (reason == REASON_SNOOZED && snoozeHandler.owns(sbn.key) || reason == REASON_GROUP_SUMMARY_CANCELED) {
466	                val collateral = reason == REASON_GROUP_SUMMARY_CANCELED &&
467	                    summaryCancellations.causedCascade(sbn.groupKey)
468	                if (reason == REASON_GROUP_SUMMARY_CANCELED && !collateral) {
469	                    coordinator.captureEvent(sbn.key, removed = true)
470	                    actionStore.remove(sbn.key)
471	                }
472	                val removal = Work.NativeRemoval(sbn.key, reason, System.currentTimeMillis(),
473	                    collateral, sbn.postTime)
474	                if (!intake.offer(removal)) {
475	                    serviceScope.launch {
476	                        snoozeWork.withLock { processNativeRemoval(removal) }
477	                    }
478	                }
479	            }
480	        }
481	        if (sbn != null) {
482	            val ownProxy = sbn.packageName == packageName && sbn.tag?.startsWith(PROXY_TAG) == true
483	            val originalId = if (ownProxy) sbn.tag!!.removePrefix(PROXY_TAG) else sbn.key
484	            val removal = NotificationRemovalMapper.fromReason(reason)
485	            if (removal != null && (ownProxy || sbn.packageName != packageName)) {
486	                // A removal remains visible to batch authorization even when the bounded mailbox is full.
487	                val order = coordinator.captureEvent(originalId, removed = true)
488	                actionStore.remove(originalId)
489	                intake.offer(Work.Removed(originalId, removal, order))
490	                NotificationDiagnostics.counter("farhan.actions.retained", actionStore.size())
491	            }
492	        }
493	        super.onNotificationRemoved(sbn, rankingMap, reason)
494	    }
