504	    private fun applyDynamicAdjustments(
505	        base: NotificationPriority,
506	        packageName: String,
507	    ): Pair<NotificationPriority, String> {
508	        val counts = rateTracker.record(packageName)
509	        val floodThreshold = notificationFilterUseCases.getDashboardSettings.getFloodThreshold()
510	
511	        if (counts.lastTenMinutes >= floodThreshold) {
512	            return Pair(base.degraded(2), "Flood – ${counts.lastTenMinutes} in 10 min")
513	        }
514	
515	        if (counts.lastHour >= CHATTER_HOUR_THRESHOLD) {
516	            return Pair(base.degraded(1), "Chatter – ${counts.lastHour}/hr")
517	        }
518	
519	        return Pair(base, "Category default")
520	    }
521	
522	    private fun createProxyNotificationChannel() {
523	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
524	            val channel = NotificationChannel(
525	                PROXY_CHANNEL_ID,
526	                "Farhan — Delivered Notifications",
527	                NotificationManager.IMPORTANCE_HIGH
528	            ).apply {
529	                description = "Notifications delivered by Farhan according to your schedule"
530	                enableVibration(true)
531	                enableLights(true)
532	            }
533	            val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
534	            nm.createNotificationChannel(channel)
535	        }
536	    }
537	}
